 #[test]fn all_twelve_nonapc_definitions_take_the_original_kind_origin_attributes_and_fresh_group(){
  for(kind,definition,eq)in[("cannon",5,0),("medium",8,1),("missile",21,9),("gatling",22,11),("howitzer",23,12),("launcher",24,6),("heavy",26,5),("light",29,8),("jeep",33,13),("crane",35,15),("firetruck",37,14),("apc",58,10)]{
   let(mut g,carrier,actor)=field(kind,definition,eq);let ai=g.units.iter().position(|u|u.id==actor).unwrap();let slot=g.units[ai].native_slot;let previous_group=g.native_group_rosters.group_slot(0,7).unwrap();
   //Type58 is an admitted alternateOBJECT that takes50be0's default branch.
   //Its unused UI classification is outside this entry callback fixture.
   if definition==58{let object=g.native_object_slot(carrier).unwrap();g.units[ai].order="enter".into();g.units[ai].target=Some(carrier);let slot=slot.unwrap();g.native_group_rosters.record_contact_target(slot,object);let m=g.native_group_rosters.members[slot].as_mut().unwrap();m.contact_order=3;m.flags31|=8;}
   assert!(g.update_native_hardware_entry(ai),"{kind}");let c=g.units.iter().find(|u|u.id==carrier).unwrap();assert_eq!(c.team,0,"{kind}");assert_eq!(c.native_slot,slot);assert_eq!(c.crew.as_ref().unwrap().hp,17.);assert_eq!(c.grenades,3);assert_eq!(c.original_combat.as_ref().unwrap().aim_skill,83);assert_eq!(c.native_order5c,0);assert_eq!(c.order,"guard");assert!(g.units[ai].native_slot.is_none());
   let source=entry::equipment_attributes(eq).unwrap();let vehicle=![5,21,22,23].contains(&definition);let point=entry::occupied_origin(definition,[320,320],vehicle);assert_eq!((c.x,c.y),(f64::from(point[0])*2.,f64::from(point[1])*2.));let mut attrs=entry::HardwareAttributes::default();attrs.take_over(source,80,15);let profile=attrs.initialize_occupied(definition,vehicle);assert_eq!((c.kind.as_str(),c.native_class7c,c.native_phase35),(profile.kind,profile.class,profile.phase));assert_eq!((c.angle,c.aim),(native_math::angle(6),native_math::angle(6)));assert_eq!(c.original_combat.as_ref().unwrap().projectile_speed,Some(source.byte(25)));assert_ne!(g.native_group_rosters.group_slot(c.team,c.squad),Some(previous_group));assert_eq!(g.native_group_rosters.pool[previous_group].roster[18],2);assert!(g.native_object_slot(carrier).is_none());
  }
 }
